from lib import *
S = SS('j278')
steps = [
    step("@Version(Hibernate 6.6.4 + PostgreSQL 16):两个 EntityManager 都加载 alice(version = 0、balance = 100)。EM1 加 50 并提交成功,发出 update Acc set balance=?,owner=?,version=? where id=? and version=?,version 变成 1;EM2 加 30 并提交,同一条 UPDATE 带着旧版本号 0,影响 0 行,抛 RollbackException ← OptimisticLockException ← StaleObjectStateException(Row was updated or deleted by another transaction);最终库里 balance = 150、version = 1。没有真正修改任何字段再提交,不发 UPDATE,version 仍是 1。", t=tl(S(1)), done=lidx(S(1), '两个 EntityManager 都加载 alice', 'EM1 加 50 并提交成功', 'update Acc set balance'), mark=lidx(S(1), 'EM2 加 30 并提交', '最终库里', '没有真正修改任何字段再提交'), kv=KV([['EM1 提交', 'where version = 0 成功,version → 1'], ['EM2 提交', 'where version = 0 影响 0 行,抛 OptimisticLockException'], ['没改字段', '不发 UPDATE,version 不变']], ['EM2 提交'])),
    step("LockModeType.OPTIMISTIC:EM1 以 OPTIMISTIC 读 alice 但不修改,EM2 随后修改并提交;EM1 提交时抛 RollbackException ← OptimisticLockException ← OptimisticEntityLockException(Newer version [1] of entity found in database)——只读也检测到了冲突。对照:EM1 用默认锁模式读 alice,EM2 同样修改并提交,EM1 提交成功,没有任何检查(读到的数据已经过期却不知道)。OPTIMISTIC_FORCE_INCREMENT 读 bob 但不修改:提交时发 update Acc set version=? where id=? and version=?,version 0 → 1,用来保护聚合根。", t=tl(S(2)), done=lidx(S(2), 'EM1 以 OPTIMISTIC 读了 alice', 'OptimisticEntityLockException'), mark=lidx(S(2), '对照:EM1 用默认锁模式', 'EM1 提交成功', 'OPTIMISTIC_FORCE_INCREMENT'), kv=KV([['OPTIMISTIC 读', '提交时检查版本,冲突抛 OptimisticLockException'], ['默认锁模式读', '提交成功,不检查'], ['OPTIMISTIC_FORCE_INCREMENT', '提交时强制 version + 1']], ['OPTIMISTIC 读'])),
    step("PESSIMISTIC_WRITE:Hibernate 在 PostgreSQL 上发出 select … for no key update。EM1 持有 alice 的行锁,线程 2 的 PESSIMISTIC_WRITE 等了约 800 ms 仍未拿到,EM1 提交之后线程 2 拿到锁,共等 807 ms。jakarta.persistence.lock.timeout = 0 变成 for no key update nowait,线程 2 在 6 ms 内抛 LockTimeoutException ← PessimisticLockException ← PSQLException(could not obtain lock on row,SQLState 55P03);timeout = -2 变成 skip locked,find 返回 null(0 ms),查询返回 1 行(跳过被锁的 alice,只返回 bob)。timeout = 1000 ms:2.5 秒之后线程仍在等待——PostgreSQL 方言不支持大于 0 的锁超时,设置被忽略,一直等到 EM1 回滚(共 2508 ms)。", t=tl(S(3)), done=lidx(S(3), 'for no key update', 'EM1 以 PESSIMISTIC_WRITE 读 alice', '线程 2 的 PESSIMISTIC_WRITE 已经等了约 800 ms', 'EM1 提交释放锁之后'), mark=lidx(S(3), 'nowait', 'skip locked', 'SKIP LOCKED 的查询', 'timeout = 1000 ms', 'EM1 回滚之后'), b=bars([['普通 PESSIMISTIC_WRITE 等待', 807, '807 ms'], ['NOWAIT 失败用时', 6, '6 ms'], ['SKIP LOCKED 用时', 0, '0 ms'], ['timeout=1000 实际等待', 2508, '2508 ms']], 2510, done=[0, 1, 2, 3]), kv=KV([['PESSIMISTIC_WRITE', 'for no key update,阻塞到对方提交'], ['timeout = 0 / -2', 'nowait(55P03)/ skip locked'], ['timeout = 1000', '被 PostgreSQL 方言忽略,一直等']], ['timeout = 1000'])),
    step("死锁:线程 1 先锁 alice 再锁 bob,线程 2 先锁 bob 再锁 alice。PostgreSQL 检测到死锁,从两个事务各自锁好第一行到有一方失败用了约 1015 ms(deadlock_timeout 默认 1 秒);线程 1 抛 OptimisticLockException ← LockAcquisitionException ← PSQLException: deadlock detected,线程 2 提交成功。被选作牺牲者的是其中一个事务,JPA 把它包装成 OptimisticLockException(名字有误导性);对多行加锁要用固定顺序。", t=tl(S(4)), done=lidx(S(4), '线程 1(先锁 alice 再锁 bob)'), mark=lidx(S(4), '线程 2(先锁 bob 再锁 alice)', '约 1015 ms'), kv=KV([['死锁检测', '约 1 秒(deadlock_timeout)后,一方被中止'], ['异常类型', 'OptimisticLockException ← LockAcquisitionException ← PSQLException(deadlock detected)']], ['异常类型'])),
    step("计数器基准(8 个线程各对同一行做 200 次 +1,期望 1600):无锁(没有 @Version)最终计数 253,丢失 1347 次更新,0.22 s;乐观锁(@Version)+ 冲突后重试:最终计数 1600 正确,重试 6216 次,0.72 s(约 2229 次提交/秒);悲观锁(PESSIMISTIC_WRITE):最终计数 1600 正确,0 次重试,0.19 s(约 8460 次提交/秒)。竞争激烈时,乐观锁的重试成本很高(6216 次重试完成了 1600 次提交),悲观锁串行化反而更快;乐观锁适合冲突少的场景。", t=tl(S(5)), done=lidx(S(5), '无锁(没有 @Version)'), mark=lidx(S(5), '乐观锁(@Version)', '悲观锁(PESSIMISTIC_WRITE)'), b=bars([['无锁:最终计数', 253, '253 / 1600'], ['乐观锁:重试次数', 6216, '6216'], ['乐观锁:提交/秒', 2229, '2229'], ['悲观锁:提交/秒', 8460, '8460']], 8460, done=[0, 1, 2, 3]), kv=KV([['无锁', '丢失 1347 / 1600 次更新'], ['乐观锁 + 重试', '正确,6216 次重试,约 2229 次提交/秒'], ['悲观锁', '正确,0 次重试,约 8460 次提交/秒']], ['无锁'])),
]
A = mkartj('j278', 278, 'Java,JPA,Hibernate,乐观锁,悲观锁,死锁,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 JPA 乐观与悲观锁:@Version 的 UPDATE 带 where version = ?,冲突抛 OptimisticLockException;PESSIMISTIC_WRITE 是 for no key update,nowait / skip locked 可用,但大于 0 的锁超时被忽略;死锁约 1 秒后检测并被包装成 OptimisticLockException;8 线程计数器:无锁丢失 1347 / 1600 次,乐观重试 6216 次,悲观最快。',
    '并发修改同一行时,JPA 给出两种锁:乐观与悲观。这篇用真实的 SQL、两个线程的阻塞与死锁,以及一个 8 线程的计数器基准,量出它们各自的行为、边界和代价。',
    [('0 行', '@Version 乐观锁:第二个事务带着旧版本号提交时 UPDATE 影响的行数(随后抛 OptimisticLockException)'), ('1347 / 1600', '8 线程各 +1 共 200 次,无锁时丢失的更新数(最终计数 253)'), ('6216 次', '乐观锁 + 重试在同样的竞争下的重试次数(悲观锁 0 次,约 8460 次提交/秒 vs 乐观约 2229)')],
    [('@Version', None), ('OPTIMISTIC 锁模式', None), ('PESSIMISTIC_WRITE', None), ('死锁', None), ('计数器基准', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15(默认 READ COMMITTED,deadlock_timeout = 1 s);每个线程自己的 EntityManager;计数器基准是单次运行(重试次数与耗时每次会不同)', '没有验证:Spring 的 @Retryable / @Lock、PESSIMISTIC_READ(for share)与 PESSIMISTIC_FORCE_INCREMENT、MySQL / Oracle 方言对锁超时的支持、@Version 的类型(Instant / Integer)与溢出、REPEATABLE READ / SERIALIZABLE 下的行为、分布式锁'], 'JPA 乐观锁与悲观锁')
